import { useRef, useState } from "react";

import { ApiKeyManager, type ApiKeyItem, type CreatedApiKey } from "@/components/trading/api-key-manager";

// Illustrative, obviously fake keys only. Real keys are generated by your backend and returned through `createdKey`.
const KEYS: ApiKeyItem[] = [
  {
    key: "ed25519:DEMOxKEYxONExNOTxREALxAAAAAAAAAAAAAAAAAAAAAAAAAAA",
    label: "Market maker bot",
    permissions: ["read", "trading"],
    ipAllowlist: ["203.0.113.24", "203.0.113.25"],
    createdAt: Date.UTC(2026, 6, 2),
    expiresAt: Date.UTC(2027, 0, 2),
  },
  {
    key: "ed25519:DEMOxKEYxTWOxNOTxREALxBBBBBBBBBBBBBBBBBBBBBBBBBBB",
    label: "Portfolio dashboard",
    permissions: ["read"],
    createdAt: Date.UTC(2026, 8, 14),
    expiresAt: null,
  },
];

export default function ApiKeyManagerDemo() {
  const [keys, setKeys] = useState(KEYS);
  const [created, setCreated] = useState<CreatedApiKey | null>(null);
  const count = useRef(0);
  return (
    <div className="w-full max-w-4xl">
      <ApiKeyManager
        keys={keys}
        accountId="0x3e9fb1c07d2a64e5b8f0c1a2d3e4f5a6b7c8d9e0"
        userId="104382"
        onCreate={({ permissions, ipAllowlist }) => {
          count.current += 1;
          // A fixed placeholder — never generate keys in the client.
          const key = `ed25519:DEMOxKEYxNEWxNOTxREALx${String(count.current).padStart(3, "0")}`;
          setKeys((list) => [{ key, permissions, ipAllowlist, createdAt: Date.UTC(2026, 9, 22), expiresAt: Date.UTC(2027, 3, 22) }, ...list]);
          setCreated({ key, secret: "ed25519:DEMOxSECRETxNOTxREALxSHOWNxONCE", permissions, ipAllowlist });
        }}
        createdKey={created}
        onCreatedKeyDismiss={() => setCreated(null)}
        onRevoke={(item) => setKeys((list) => list.filter((k) => k.key !== item.key))}
        onReadGuide={() => {}}
      />
    </div>
  );
}
